<?php
require_once __DIR__ . '/../libs/db.php';

try {
    // 1. Move bugged income from old booster variables to the new growth engine variables
    
    // We only want to move money that came from 'booster_income' transactions in the 'booster_10_wallet'
    // but were actually generated by the Growth Engine.
    // Let's identify the users who got Growth Engine payouts.
    // In BoosterEngine, the transaction narration was "Earned $10.00 from Booster #% 1x3 cycle completion"
    
    $stmt = $pdo->query("SELECT user_id, SUM(amount) as total FROM transactions WHERE transaction_type = 'booster_income' AND wallet_type = 'booster_10_wallet' AND narration LIKE '%1x3 cycle completion%' GROUP BY user_id");
    $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
    
    $count = 0;
    foreach($rows as $r) {
        $uid = $r['user_id'];
        $amt = $r['total'];
        
        $pdo->exec("UPDATE user_financial_summary SET 
            growth_engine_wallet = growth_engine_wallet + $amt, 
            booster_10_wallet = booster_10_wallet - $amt,
            total_growth_engine_income = total_growth_engine_income + $amt,
            total_booster_income = total_booster_income - $amt
            WHERE user_id = '$uid'");
            
        $count++;
    }
    
    // 2. Fix the transaction logs
    $pdo->exec("UPDATE transactions SET wallet_type = 'growth_engine_wallet', transaction_type = 'growth_engine_income' WHERE transaction_type = 'booster_income' AND wallet_type = 'booster_10_wallet' AND narration LIKE '%1x3 cycle completion%'");

    echo "[SUCCESS] Repaired balances for $count users. The $10 has been moved to the growth engine wallet.\n";
} catch (Exception $e) {
    echo "[ERROR] " . $e->getMessage() . "\n";
}
?>
